package io.cortavyn.model.api;
import java.lang.reflect.*; import java.util.*; import org.jspecify.annotations.Nullable;
final class StructuredSchemas { static StructuredOutputSchema fromRecord(Class<?> type){SchemaName n=type.getAnnotation(SchemaName.class);return new StructuredOutputSchema(n==null?type.getSimpleName():n.value(),object(type),true);} private static Map<String,Object> object(Class<?> type){if(!type.isRecord())throw new IllegalArgumentException("structured output type must be a record: "+type.getName());Map<String,Object> p=new LinkedHashMap<>();List<String> r=new ArrayList<>();for(RecordComponent c:type.getRecordComponents()){Map<String,Object> s=schema(c.getGenericType());SchemaDescription d=c.getAnnotation(SchemaDescription.class);if(d!=null)s.put("description",d.value());p.put(c.getName(),s);if(!c.getAnnotatedType().isAnnotationPresent(Nullable.class))r.add(c.getName());}Map<String,Object> root=new LinkedHashMap<>();root.put("type","object");root.put("properties",p);if(!r.isEmpty())root.put("required",r);root.put("additionalProperties",false);return root;} private static Map<String,Object> schema(Type type){if(type instanceof ParameterizedType p&&p.getRawType() instanceof Class<?> raw&&Iterable.class.isAssignableFrom(raw)){Map<String,Object>s=new LinkedHashMap<>();s.put("type","array");s.put("items",schema(p.getActualTypeArguments()[0]));return s;}if(type instanceof Class<?> c){if(c.isRecord())return object(c);if(c.isEnum()){List<String>v=new ArrayList<>();for(Object e:c.getEnumConstants())v.add(((Enum<?>)e).name());return new LinkedHashMap<>(Map.of("type","string","enum",v));}return new LinkedHashMap<>(Map.of("type",kind(c)));}return new LinkedHashMap<>();} private static String kind(Class<?> t){if(t==boolean.class||t==Boolean.class)return "boolean";if(t==byte.class||t==Byte.class||t==short.class||t==Short.class||t==int.class||t==Integer.class||t==long.class||t==Long.class)return "integer";if(t==double.class||t==Double.class||t==float.class||t==Float.class)return "number";return "string";} private StructuredSchemas(){} }
